BEGIN;

INSERT INTO vi_company_base (code, name, exchange, industry, currency, volume_label, volume_unit, price_label, price_unit, is_default, profile, notes)
VALUES ('601668.SH', '中国建筑', '上海证券交易所', '建筑装饰（房建、基建、地产开发）', '人民币', '新签合同总额（建筑新签＋地产合约销售）', '亿元',
        '收入转化率（营业收入÷新签合同总额）', '比率（0.46＝每 1 元新签对应当年 0.46 元收入）', FALSE, '全球最大的投资建设集团：房屋建筑（2025 年收入 12,342 亿元，毛利率 8.4%）、基础设施（5,432 亿元，9.9%）、房地产开发（2,844 亿元，14.4%，含港股上市的中国海外发展/中海地产与中建地产）、勘察设计。2025 年新签合同总额 4.55 万亿元、营业收入 2.08 万亿元、归母净利 390.7 亿元。控股股东中国建筑集团持股约 57.7%。
怎么赚钱：先签合同（新签合同总额＝建筑新签＋地产合约销售），再按施工进度确认收入，赚 8%—11% 的毛利，扣掉费用后核心利润率只有 6%—7%（未扣减值）。规模大、毛利薄、资产重：2.08 万亿收入背后是 3.56 万亿总资产和 77% 的资产负债率，应收账款＋合同资产已超过 1 万亿元。
本质：一家“薄利、高周转、靠信用垫资”的总承包商，加一块周期性地产。价值取决于两件事：账面利润能否变成现金（应收与合同资产能否收回、减值是否足够），以及在建筑与地产总量下行时，收入和利润会掉到哪里。', '主要风险：地方政府与城投付款能力（政府背景业主占房建基建项目 40% 以上）、存量 PPP 与 BT 项目回款、地产存货跌价、风险房企应收、收入持续下滑而合同额不降（订单含金量下降）、少数股东与永续债分走利润（少数股东损益占净利约 27%）、央企目标函数不只是股东回报。')
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, exchange = EXCLUDED.exchange, industry = EXCLUDED.industry,
  currency = EXCLUDED.currency, volume_label = EXCLUDED.volume_label, volume_unit = EXCLUDED.volume_unit,
  price_label = EXCLUDED.price_label, price_unit = EXCLUDED.price_unit, profile = EXCLUDED.profile, notes = EXCLUDED.notes;

