VALUES ('601668.SH.PRICE', '中国建筑收盘价', '元', '行情', (SELECT id FROM vi_company_base WHERE code = '601668.SH'), '腾讯行情（自动采集）；2025-10-20—2026-10-22 日线由腾讯 K 线接口一次性补齐（不复权）',
        '交易日', 0, 50, '股价只进入对比层，不进入经营假设。2026-07-16 除息 0.2718 元，不复权序列在这一天有一个跳空。')
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, unit = EXCLUDED.unit, category = EXCLUDED.category, company_id = EXCLUDED.company_id,
  source_name = EXCLUDED.source_name, frequency = EXCLUDED.frequency, valid_min = EXCLUDED.valid_min, valid_max = EXCLUDED.valid_max, notes = EXCLUDED.notes;

UPDATE vi_company_base SET price_metric_id = (SELECT id FROM vi_metric_base WHERE code = '601668.SH.PRICE') WHERE code = '601668.SH';

INSERT INTO vi_collector_base (name, metric_id, url, parser, parser_param, enabled, max_lag_days, notes)
SELECT '中国建筑股价（腾讯行情）', (SELECT id FROM vi_metric_base WHERE code = '601668.SH.PRICE'), 'https://qt.gtimg.cn/q=sh601668', 'tencent_quote', 'sh601668', TRUE, 7, '返回 GBK 编码，名称会乱码但不影响按“~”分段解析。'
WHERE NOT EXISTS (SELECT 1 FROM vi_collector_base WHERE name = '中国建筑股价（腾讯行情）');
UPDATE vi_collector_base SET metric_id = (SELECT id FROM vi_metric_base WHERE code = '601668.SH.PRICE'), url = 'https://qt.gtimg.cn/q=sh601668', parser = 'tencent_quote', parser_param = 'sh601668',
  max_lag_days = 7, notes = '返回 GBK 编码，名称会乱码但不影响按“~”分段解析。' WHERE name = '中国建筑股价（腾讯行情）';

