((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '全球最大承包商：ENR 第一、评级 A/A2/A、承建国内绝大多数 300 米以上超高层', '经营', '2024 年年报：ENR“全球最大 250 家工程承包商”首位，《财富》世界 500 强第 14 位；标普、穆迪、惠誉评级 A/A2/A、展望稳定，为全球建筑行业最高信用评级；经营区域覆盖全国各省区市与海外近百个国家和地区；“国内绝大多数的 300 米以上超高层建筑，众多技术含量高、结构形式复杂的建筑均由中国建筑承建”。', NULL, NULL, '2024', '2025-04-16', '已核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND title = '中国建筑 2024 年年度报告' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '成本构成：分包 37%、原材料 24%、劳务 12%', '经营', '2025 年年报“费用按性质分类”（营业成本＋销售、管理、研发费用，合计 19,630 亿元）：分包成本 7,202 亿元（37%）、耗用原材料 4,671 亿元（24%）、劳务支出 2,367 亿元（12%）、房地产开发产品结转 2,209 亿元（11%）、其他施工成本 1,624 亿元（8%）、职工薪酬 1,051 亿元（5%）。', 7202, '亿元', '2025', '2025-12-31', '已核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND title = '中国建筑 2025 年年度报告' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '客户结构：政府背景业主占四成以上，住宅占房建订单两成以内', '经营', '公司董办（2026-07）：政府背景业主占房建、基建项目 40% 以上；住宅占房建订单 20% 以内。', 0.4, '比率', '2026', '2026-07-14', '待核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND title = '券商策略会交流纪要：公司董办（中泰证券，2026-07-14）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '地产同业 2025 年：中海权益销售第一，保利归母仅 10 亿元', '经营', '2025 年权益销售额：中海地产 2,311 亿元（行业第一）、保利发展 2,000 亿元、华润置地 1,593 亿元（全口径 2,512、2,530、2,336 亿元，同比 −19.1%、−21.7%、−10.5%）；全国新建商品房销售额 83,937 亿元（−12.6%）。保利发展 2025 年营收 3,081 亿元、毛利率 12.8%、归母 10.3 亿元（资产减值 64.8 亿元）；华润置地开发结算毛利率 15.5%、归母 254.2 亿元，经营性不动产与轻资产贡献约一半核心利润。2026 年 1—5 月全口径销售：中海 1,030 亿元（+14.0%）、保利 1,053 亿元（−9.3%）、华润 935 亿元（+7.7%）。', 2311, '亿元', '2025', '2026-06-02', '待核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND title = '岗底斯：地产同业销售排名与 2025 年业绩（克而瑞、中指院、公司公告）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '中国海外发展 2025 年：毛利率 15.5%，股东应占溢利 126.9 亿元', '经营', '中国海外发展（中海地产）2025 年业绩公告：收入 1,680.9 亿元（−9.2%）、毛利率 15.5%（2024 年 17.7%）、股东应占溢利 126.9 亿元（−18.8%）、平均融资成本 2.8%、净借贷比率 34.2%；已售未结转约 1,805 亿元（毛利率约 18.4%，60%—70% 预计 2026 年结转）；一线城市权益拿地金额占 74%；分销与行政费用约占收入 4%（管理层称行业最低）。', 126.9, '亿元', '2025', '2026-03-31', '待核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND title = '岗底斯：地产同业销售排名与 2025 年业绩（克而瑞、中指院、公司公告）' LIMIT 1));

INSERT INTO vi_thesis_base (company_id, code, title, category, status, confidence, bull_case, bear_case, bull_rebuttal, bear_rebuttal, verdict, decisive_evidence, mind_changer, model_impact, external_view, debated_on, check_metric, check_op, check_threshold, check_years) VALUES
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'T1', '规模与信用让它在行业下行期继续拿份额', '壁垒', '成立', '中', '1）份额在升：全国建筑业新签 2025 年下降 5.51%，公司建筑新签反而增长 1.7%，占全国的比重从约 12.2% 升到约 13.2%；管理层称 2026 年上半年市场占有率又提高 2.2 个百分点。2）原因是信用与大项目能力（M1、M2）：业主缺钱时，能垫资、能干复杂项目的总包商才拿得到项目，民企与弱地方国企在退出。3）订单在向资金方更可靠的领域转移：工业厂房、能源、数据中心增长，住宅压到房建订单的两成以内（B1）。', '1）份额上升的一部分来自“愿意垫资”：下行期拿到的可能是付款条件更差的订单，应收＋合同资产两年增长 70%（B9、T4）。2）规模没有带来更高的利润率：毛利率与央企同业持平（M1），新签规模本身是伪壁垒（M5）。3）另外七家央企有同样的信用与资质，央企之间同质化竞争激烈（V8）。', '新接项目毛利率 +0.2pt、住宅占比压到两成以内、PPP 不再新增：公司在拿份额的同时收紧了项目质量；民企退出后，集中度上升本身会改善竞争格局。', '选项目的效果要看两三年后的回款与减值，现在只有一年半的数据；只要应收比收入涨得快，份额就是用资产负债表“买”来的。', '成立：份额优势真实、可度量，来自央企信用与大项目能力，复制要多年。订单总量稳住了（2026 年 1—9 月 −0.1%），但变成收入的速度在变慢（T2），也没有变成更高的利润率或 ROE（T7）。', '建筑新签占全国的比重（中建协年度统计）；订单结构（工业、能源、住宅、海外占比）；新接项目毛利率；应收增速与收入增速之差。', '改判为观察：新签降幅连续两年大于全国（份额下降）。自动检查：新签合同总额同比连续两年低于 −5%（规模优势失效）。', NULL, '岗底斯同业对比：中国建筑新签占全国建筑业比例逆势提升至 13.16%，工业厂房增速领先同梯队（同业新签见 M2）；卖方普遍把“央企龙头份额提升”作为看多理由。', '2026-10-23', '业务量同比', '<', -0.05, 2),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'T2', '收入在 2027 年见底（收入转化率停在约 0.405）', '经营', '存疑', '中', '1）订单不缺：新签三年稳定，2026 年前三季度基本持平（B5）。2）转化率下降有周期原因：开工少、业主资金紧、工期拉长；化债推进后，结算会恢复一部分。3）地产结转比建筑稳定：管理层预计未来两三年地产营收大体平稳（事实摘录）。', '1）领先指标还在下滑：房建新开工面积 2026 年 1—9 月 −18.1%、竣工 −11.6%，新开工是 1—2 年后收入的领先指标，2027 年收入可能继续两位数下滑。2）基建新签 −5.8% 会滞后传导到收入；住宅订单还在收缩。3）2026 年收入约 −10%，比管理层目标（+1%）差得多；收入转化率从约 0.54 降到约 0.41，还没有止跌的迹象（伪壁垒 M5）。', '工业厂房、能源、数据中心订单增速高，这类项目开工快、工期短，会比住宅更快变成收入。', '2026 年上半年工业厂房新签 +24.2%，房建收入仍 −18%：新领域的体量还撑不住住宅与基建的下滑。', '存疑：反方占优。领先指标（新开工）仍在两位数下滑，2027 年见底的假设偏乐观，是经营模型最需要验证的一条；悲观情景（收入较基准 −6.9%）覆盖了反方的路径。', '季度收入同比；房建新开工面积；收入转化率；在手合同的开工与结算节奏。', '改判为观察：2026 年四季度与 2027 年一季度收入降幅收窄到 −5% 以内。自动检查（触发即证伪）：营业收入同比连续两年低于 −5%（2026 年大概率低于 −5%，若 2027 年仍低于 −5% 即触发）。', NULL, '卖方大多认为 2027 年收入能恢复增长（见 J-P 反证）；对 2026—2028 年归母净利的一致预期约 370—392 亿元，中报后普遍下调（事实摘录）。', '2026-10-23', '营业收入同比', '<', -0.05, 2),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'T3', '毛利率守得住：施工在升、地产在降，综合约 10%', '经营', '成立', '中', '1）施工毛利率在升：2025 年提高 0.7pt 到 8.8%，2026 年上半年综合毛利率 10.3%，来自选项目与成本管控（M4）。2）核心利润率（不含减值）跨周期稳定在 6%—7%（事实摘录）：利润下滑来自收入与减值，不是施工毛利（B9）。3）订单结构向工业、能源转移，住宅占比下降（B1）。', '1）收入下降时费用刚性：2026 年上半年期间费用率 +0.44pt，吃掉一部分毛利率的提升。2）毛利率提升可能部分来自少确认低毛利项目，或结算时的一次性调整，不可持续。3）地产毛利率在降：2025 年 14.4%（−2.9pt）、2026 年上半年 15.0%（−1.0pt），2021—2023 年拿的高价地还在结转（M3）；地产毛利率若跌到 12%，综合毛利率约降 0.3pt。4）海外毛利率低（2025 年 2.8%），海外占比上升会拉低综合毛利率。', '中海已售未结转资源的毛利率约 18.4%（60%—70% 在 2026 年结转），地产毛利率短期有支撑；海外 2026 年上半年毛利率已回到 6.2%。', '已售未结转的毛利率是公司口径，未扣土地增值税与后续减值；地产销售面积 2026 年 1—9 月 −30.6%，2028 年后的结转规模会明显下降。', '成立：施工毛利率在改善、核心利润率跨周期稳定；地产毛利率在降，但收入占比约 15%。要盯的是地产毛利率（12% 是红线）和费用率。', '分业务毛利率（半年报、年报）；新接项目毛利率；地产结转毛利率与中国海外发展业绩；期间费用率。', '改判为观察：施工毛利率连续两个半年度下降，或地产业务毛利率低于 12%（看年报分部数据，不设自动检查）。自动检查：年度毛利率连续两年低于 9%。', NULL, '岗底斯同业对比：房建毛利率 2025 年 +1pt 是积极信号，地产毛利率 −2.9pt 之后是否见底是验证点。', '2026-10-23', '毛利率', '<', 0.09, 2),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'T4', '利润正在变成现金：化债与收款让营运资本占用逐年下降', '财务', '观察', '低', '1）经营现金流 2023—2025 年 110、158、205 亿元逐年改善；2026 年上半年同比少流出 544 亿元，二季度单季 +485 亿元；管理层称全年经营现金流在上年基础上增长。2）化债：2024 年 11 月起的一揽子政策让政府债权回收明显加快（2025 年回收、逾期减少都在 1,500 亿元左右，2026 年上半年又清收逾期超 800 亿元）；央企债权在化债中的优先级较高。3）PPP 不再新增，存量多数已进入运营回款期（M7）；资本开支不大（B9）。', '1）应收＋合同资产两年增长 70%，2026 年上半年又增加约 1,745 亿元到 11,790 亿元，而收入在降：每 1 元收入要垫的应收与合同资产从 0.26 元升到 0.48 元（B9）。2）经营现金流的改善部分靠拖延付给供应商：应付票据及账款同步大增（V1）。3）客户是政府与城投（B1）：化债力度较去年减弱（管理层）；PPP 相关的其他非流动资产与长期应收款约 4,900 亿元，回款依赖地方财政（伪壁垒 M6、M7）。', '上半年应收增加有季节性（年底集中收款），2026 年下半年和 2027 年的收款会验证；拖欠供应商受监管约束、不能无限持续，反而迫使公司加快清收。', '化债一旦退坡，营运资本占用可能长期停在高位，股息就要靠借款支付（J-WC 反证）。', '观察：方向向好（经营现金流三年改善、化债回款），但现金转化率仍很低（0.53 倍），应收还在涨。这是本模型的第二大判断（J-WC）：现金支持价值能否接近股息贴现价值取决于它。', '年度经营现金流÷归母净利；应收＋合同资产增速与收入增速之差；政府债权回收与逾期金额；PPP 回款；应付账款变化。', '改判为成立：经营现金流连续两年超过 300 亿元，且应收＋合同资产不再增长。改判为存疑：化债资金退坡、政府逾期债权回升，或应收增速连续两年高于收入增速 15pt。自动检查：经营现金流÷归母净利润连续两年低于 0.3。', NULL, '管理层（2026-08）：化债力度较去年减弱，但最难的时候已经过去。岗底斯同业对比：中国交建两金压降较好，可作为行业回款环境的参照。岗底斯观点 PK 调用超时（2026-10-23）。', '2026-10-23', '经营现金流÷归母净利润', '<', 0.3, 2),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'T5', '负债可控：杠杆不再上升', '财务', '观察', '中', '综合融资成本约 2%、行业最高信用评级、货币资金 4,117 亿元（M1）；模型假设 2026—2028 年再借 350 亿元，之后每年还 50—80 亿元（J-DEBT）。', '带息负债从 2018 年 4,237 亿元涨到 2025 年 9,405 亿元，主要用来垫付应收与合同资产；净负债÷EBITDA 从 2023 年约 3.4 倍升到 2025 年约 4.9 倍；货币资金含受限资金与预售监管资金，真实可用的现金更少。', NULL, NULL, '观察：央企信用让融资不是问题，但杠杆上升在吞噬股东回报。', '带息负债、净负债÷EBITDA、利息费用；短债占比；资产负债率（国资委考核线）。', '自动检查：净负债÷EBITDA 大于 6 倍。', NULL, NULL, NULL, '净负债÷EBITDA', '>', 6, 1),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'T6', '治理与股东回报：每股股息不降，派息率逐年提高', '治理', '成立', '中', '1）每股股息 2023—2025 年度 0.2715—0.2718 元，派息率由 2018 年约 18% 升到 2025 年 28.7%；管理层承诺 2026 年度每股派息保持平稳；上市以来累计分红 1,040 亿元。2）控股股东持股 57.73%，上市以来第 8 次增持、无减持（2026 年计划增持 5—10 亿元）。3）国资委市值管理与“破净”整改（2027 年底时限）要求提高股东回报，可能推动回购或提高分红，是潜在的催化剂。', '1）央企的目标函数不只是股东回报：经营目标兼顾稳增长、规模与政策任务（V11），城市更新等政策性投资回报周期长（J-CAPEX 反证）。2）利润继续下滑时，保持每股股息意味着派息率被动上升；现金流若不改善，分红实际靠借款支付（T4）。3）多层分配：少数股东分走约 27% 的净利（中国海外发展、中国建筑国际都是港股上市子公司），子公司另有永续债约 608 亿元；关联交易（中建财务公司存款）要盯。', '利润下降的年份也没有降每股股息；少数股东主要是港股上市子公司的公众股东，是透明的市场化持股。', '相对 PB 0.37 倍和留存利润的低回报（T7），28.7% 的派息率仍偏低；模型假设要到 2035 年才提高到 40%。', '成立：2026 年度每股股息基本确定，控股股东持续增持，治理整体可信；但不给治理溢价，央企目标函数与多层分配让归母股东拿到的现金少于报表利润。', '每年分红方案；国资委或公司的股东回报规划、回购；少数股东损益占比；永续债余额；关联交易；城市更新等重大投资的回报率。', '改判为观察：每股股息下调，或少数股东损益占比持续升到 35% 以上，或出现损害中小股东的关联交易。自动检查：派息率低于 25%（每股股息下调）。', NULL, '国泰海通（2025-08）：分红比例超 24%，高于其他建筑央企；卖方普遍把破净整改、市值管理作为催化剂。', '2026-10-23', '派息率', '<', 0.25, 1),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'T7', 'ROE 守在资本成本（约 7.6%）以上', '财务', '存疑', '中', '1）减值是 ROE 下降的主因：若减值回落到正常账龄水平（80—100 亿元/年），ROE 可回到 9%—10%。2）核心利润率稳定（T3），PPP 不再新增、资本开支下降，资本密度会下降。3）2025 年 ROE 7.9% 是建筑央企里最高的（岗底斯口径，同业见事实摘录）。', '1）ROE（普通股口径）2021 年约 16.5%、2023 年约 13.7%、2025 年约 8.3%，2026 年约 7%；股权资本成本约 7.6%。2）按模型路径，留存利润几乎不带来增长，长期 ROE 在资本成本以下（J-PAYOUT 反证）。3）PB 0.37 倍就是市场认为 ROE 会长期低于资本成本，应收、PPP 与地产存货的账面价值要打折（J-REL）。', '地产下行周期里市场给所有建筑央企 0.3—0.5 倍 PB，是行业性的折价；中国建筑有地产平台和同业最高的 ROE，减值回落后修复空间更大（J-REL）。', '地产平台在下行期是减值源头（T8）；修复需要减值回落和现金回收同时发生，两者都还没有看到拐点。', '存疑：反方占优。2026 年 ROE 大概率低于资本成本，模型路径下长期也在资本成本以下；低 PB 有基本面原因，对股东来说提高派息率比留存更有价值（J-PAYOUT）。', '年度 ROE；减值是否收敛（T8）；地产利润是否企稳；留存利润的增量回报。', '改判为观察：减值连续两年回落、ROE 回到 9% 以上。自动检查：ROE 连续两年低于 6%。', '不单独改参数', '岗底斯一致预期：ROE 2026—2028 年约 6.7%、6.6%、6.5%；卖方目标价 4.8—6.87 元（6—7 倍 PE 或分部估值，J-REL）。', '2026-10-23', 'ROE', '<', 0.06, 2),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'T8', '减值在 2026 年见顶、之后逐年回落', '财务', '观察', '低', '1）管理层：2026 年减值预计不超过 2025 年（258.7 亿元）；上半年 100.4 亿元以应收账款为主（53.6 亿元），存货只有 6.6 亿元，单独测试减值转回 29 亿元。2）风险房企（恒大、碧桂园、融创等）计提高峰已过：它们是 2025 年专项减值（约 150 亿元）的近一半，影响越来越小。3）政府类债权在化债中回收（T4）；地产业务聚焦一二线核心城市（M3），存货跌价比同业少。', '1）减值 2019—2025 年连升六年（35 → 259 亿元）；正常账龄计提 80—100 亿元/年，2025 年是它的 2.5 倍以上。2）公司董办：专项减值里地产存货约 1/5 强，地产存货与 PPP/BT 项目的计提“有上升苗头”；2021—2023 年拿的高价地若房价继续下跌会持续计提。3）敞口大：应收与合同资产已超过 1.1 万亿元，另有约 4,900 亿元 PPP 相关资产（Q04），计提比例未必够（敏感性见 J-IMP）；中国中冶就是减值失控的样本（竞争对手）。', '减值是估计，也可能回转；上半年的减值结构说明地产存货跌价并没有大幅增加。', '四季度通常集中计提（2025 年四季度单季归母只有 8.9 亿元），上半年的结构说明不了全年；“不超过去年”仍是 250 亿元级，远高于正常水平。', '观察：管理层给了全年上限，风险房企的拖累在减弱，但地产存货与 PPP 的计提在上升、四季度不确定。模型按 2026 年约 235 亿元、2029 年起约 180 亿元（仍是正常账龄的两倍）处理，更坏的情形用单参数试验（减值多 100 亿元/年）展示。', '年报、半年报的减值分项（应收、合同资产、存货、PPP）与减值覆盖率；风险房企应收余额；地产存货跌价；政府逾期债权。', '改判为成立：2026 年减值低于 230 亿元，且 2027 年继续回落。改判为存疑：2026 年减值超过 258.7 亿元，或单年地产存货减值超过 50 亿元，或地产业务毛利率低于 12%。不设自动检查（历史财务没有减值字段），由跟踪事项 W4、W6 手工检查。', NULL, '岗底斯同业对比：地产毛利率继续下行到 10% 以下、减值压力加大是下修触发因素；卖方中报后普遍下调 2026 年利润（中泰由 487 亿元下调到 366 亿元）。', '2026-10-23', NULL, NULL, NULL, NULL);

INSERT INTO vi_lnk_thesis_facts (thesis_id, fact_id, "createdAt", "updatedAt")
SELECT x.id, y.id, now(), now() FROM (VALUES ('T1', '2025 年新签合同总额 45,458 亿元'), ('T1', '市场份额：建筑新签约占全国 13.2%，八大央企合计约 47%'), ('T1', '全球最大承包商：ENR 第一、评级 A/A2/A、承建国内绝大多数 300 米以上超高层'), ('T1', '订单结构：工业厂房、能源、数据中心增长'), ('T2', '收入转化率从 0.54 降到 0.46，2026 年约 0.41'), ('T2', '2026 年 1—9 月新签 32,890 亿元（−0.1%），房建新开工 −18.1%'), ('T2', '2026 年上半年业绩：营收 −12%、归母 −24%'), ('T2', '2026 年目标与管理层体感'), ('T2', '地产：销售面积大降，均价上升，土储收缩'), ('T3', '毛利率：施工提升、地产下滑'), ('T3', '核心利润率稳定在 6%—7%'), ('T3', '2026 年上半年分业务：房建 −18%、地产 +15%、境外 +27%'), ('T3', '中国海外发展 2025 年：毛利率 15.5%，股东应占溢利 126.9 亿元'), ('T3', '海外：订单高增但毛利率低'), ('T4', '经营现金流：连续六年为正但远低于利润'), ('T4', '应收账款＋合同资产 10,045 亿元，两年增长 70%'), ('T4', '化债回款：2025 年政府债权回收超 1,500 亿元'), ('T4', 'PPP：2023-11 后不再新增，存量权益投资 5,951 亿元'), ('T4', '客户结构：政府背景业主占四成以上，住宅占房建订单两成以内'), ('T5', '带息负债 9,405 亿元，净负债 5,289 亿元'), ('T6', '分红：每股 0.2718 元、派息率 28.7%，2026 年度保持平稳'), ('T6', '控股股东增持 5—10 亿元，持股 57.73%'), ('T6', '少数股东分走约 27% 的净利润'), ('T7', '估值：PB 0.37 倍、PE 约 5 倍、股息率约 6%'), ('T7', '建筑央企 2025 年：毛利率都在 9%—12%，减值÷收入 0.8%—1.3%'), ('T7', '减值：2025 年 258.7 亿元，2026 年上半年 100.4 亿元'), ('T8', '减值：2025 年 258.7 亿元，2026 年上半年 100.4 亿元'), ('T8', '减值构成：风险房企近半，地产存货与 PPP/BT 有上升苗头'), ('T8', '应收账款＋合同资产 10,045 亿元，两年增长 70%'), ('T8', '地产：销售面积大降，均价上升，土储收缩'), ('T8', '建筑央企 2025 年：毛利率都在 9%—12%，减值÷收入 0.8%—1.3%')) v(k1, k2)
JOIN vi_thesis_base x ON x.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND x.code = v.k1 JOIN vi_fact_base y ON y.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND y.title = v.k2;

INSERT INTO vi_judgment_base (company_id, code, title, fact_layer, judgment, transmission, parameter, affected_years, change_threshold, no_change_condition, counter_evidence, status) VALUES
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-Q', '新签合同总额路径（业务量）', '新签合同总额 2022—2025 年 39,031、43,241、45,027、45,458 亿元；2026 年 1—9 月 32,890 亿元（−0.1%）；全年目标 4.6 万亿元。房建 +3.5%、基建 −5.8%、境外 +72%、地产 −6.5%。', '2026—2028 年 45,400 亿元（与 2025 年持平：2025 年四季度 12,535 亿元，假设今年四季度相当）；2029 年起每年 +1%（城市更新、海外、工业与能源工程对冲住宅与基建下滑）。', '营业收入＝新签合同总额×收入转化率。新签每 ±1%，收入约 ±186 亿元，利润总额约 ±12 亿元（按核心利润率 6.5%）。', '逐年假设·业务量', '2026—2035，全部情景', '年度新签偏离假设 3% 以上；连续两个季度负增长超过 5%。', '单月波动（经营简报按月披露，季末月份订单集中）。', '新签合同额是“签约口径”，包括框架协议和分期确认的大项目，含金量会变化；所以收入要看转化率（J-P），不能只看新签。', '已形成建议'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-P', '收入转化率（单价）', '营业收入÷新签合同总额：2021 年约 0.536 → 2023 年 0.524 → 2024 年 0.486 → 2025 年 0.458；2026H1 收入 −12%、新签 −1.5%。房建新开工面积 1—9 月 −18.1%，说明 2027 年收入还有下行压力。地产收入（结转）比建筑稳定。', '2026 年 0.414（全年收入约 18,800 亿元，−9.7%：上半年 −12%，下半年约 −8%）；2027 年起 0.405（收入约 18,390 亿元，再降约 2%），之后不变。即收入在 2027 年见底。', '转化率每 ±0.01，收入约 ±454 亿元、利润总额约 ±30 亿元、归母净利约 ±17 亿元。', '逐年假设·单价', '2026—2035', '三季报、年报收入与假设偏离 3% 以上；新开工面积全年降幅超过 15%。', '单季结算节奏波动。', '卖方多数假设 2027 年收入恢复正增长（国投 +5.1%），本模型更保守；若新开工继续两位数下滑，2027 年收入可能再降 5% 以上（悲观情景）。', '已形成建议'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-M', '核心利润率（付现成本）', '核心利润率（不含减值、投资收益）2019—2025 年 7.2%、6.8%、7.1%、6.3%、6.1%、6.2%、6.2%，2026H1 7.1%（下半年历年偏低：2025 年下半年 5.9%）。毛利率 2026H1 +0.9pt，新接项目毛利率 +0.2pt；期间费用率 +0.44pt。', '付现成本＝营业收入×(1−核心利润率)：2026—2027 年 6.6%、2028 年起 6.5%（2022—2025 年平均 6.2%，加施工毛利改善约 0.3pt）。', '核心利润率每 0.1pt ≈ 利润总额 19 亿元 ≈ 归母净利 10.5 亿元（约 3%）。利润对利润率极其敏感：收入大、利润薄。', '逐年假设·付现成本', '2026—2035', '连续两个半年度偏离假设 0.4pt 以上。', '单季结算结构波动。', '收入下降时费用刚性，利润率可能被动下降；地产高价地结转拉低毛利。', '已形成建议'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-IMP', '减值与其他净贡献', '资产及信用减值 2021—2025 年 126、136、143、201、259 亿元，2026H1 100 亿元，管理层称全年不超过去年；正常账龄计提约 80—100 亿元/年。投资收益由 2023 年 40 亿元降到 2025 年 8 亿元、2026H1 1.4 亿元（联营企业收益减少、应收保理的终止确认损失）。其他收益、营业外等约 +15—25 亿元/年。', '其他净贡献＝投资收益＋其他收益与营业外−减值：2026 年 −215（减值约 235），2027 年 −190，2028 年 −170，2029 年起 −160（减值约 180，即收入的 0.95%，仍是正常账龄的两倍）。', '直接进入利润总额；减值每多 100 亿元，归母净利约少 56 亿元。', '逐年假设·其他净贡献', '2026—2035', '年度减值偏离假设 40 亿元以上；风险房企、PPP 或地方政府出现新的大额违约。', '季度间计提节奏不均（四季度通常最多）；风险用情景和单参数试验展示，不机械改长期假设。', '减值是估计，可能不足，也可能回转（正反论证见 T8）。', '已形成建议'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-DA', '折旧摊销', '折旧摊销（含使用权资产、特许经营权摊销）2023—2025 年 186、190、192 亿元；2026H1 105 亿元。', '2026—2027 年 205 亿元、2028 年 206 亿元，之后每年 +1%。', '折旧是非现金费用：减少利润，所有者收益里按归母比例加回；维持资本开支按同样的归母口径扣除。', '逐年假设·折旧摊销', '2026—2035', '半年报折旧与假设偏差超过 5%。', '—', '特许经营权（PPP）进入运营后摊销会增加。', '已形成建议'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-TAX', '所得税率与少数股东占比', '有效税率 2023—2025 年 20.9%、21.6%、23.7%，2026H1 24.3%（减值部分不能抵税）；少数股东损益占净利润 26.2%、26.4%、27.1%，2026H1 25.0%。', '所得税率 24%；少数股东占比 26%。', '归母净利＝利润总额×0.76×0.74≈利润总额×56%。税率每 +1pt，归母净利约 −2.4 亿元。', '逐年假设·所得税率、少数股东占比', '2026—2035', '年报偏离 2 个百分点以上。', '—', '地产（中海，非全资）利润占比变化会改变少数股东占比。', '已形成建议'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-WC', '营运资本占用（现金桥接最大判断）', '经营现金流 2025 年 205 亿元，归母口径约 150 亿元，而归母净利＋归母折旧约 530 亿元：营运资本吃掉约 380 亿元。应收＋合同资产两年增长 70%。2026 年管理层称经营现金流将高于 2025 年。PPP 不再新增、存量进入回款期。', '营运资本增加（归母口径）：2026 年 340、2027 年 260、2028 年 200、2029 年 150、2030 年 120、2031 年 100、2032 年起 80 亿元。即经营现金流逐年改善，但长期仍有营运资本占用（业主付款越来越慢是行业常态）。', '所有者收益＝归母净利＋归母折旧−非现金收益＋投资分红−营运资本增加−维持资本。营运资本每多占用 100 亿元，当年 FCFE 少 100 亿元，约等于一年的股息。', '逐年假设·营运资本增加', '2026—2035', '年度经营现金流偏离隐含值（约 230 亿元起逐年增加）100 亿元以上；应收＋合同资产增速连续两年高于收入增速 15pt。', '上半年经营现金流为负（季节性：年底集中收款）；化债退坡的影响用情景展示，不机械改长期假设。', '若化债退坡、地方财政更紧，占用可能长期维持在 300 亿元以上，那时股息只能靠借款支付（现金支持价值会明显低于股息贴现价值）。', '已形成建议'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-CAPEX', '维持与扩张资本（归母口径）', '购建长期资产 2023—2025 年 341、198、262 亿元；投资活动净现金流 −265、−25、−322 亿元；PPP 不再新增，但城市更新、运营资产、海外投建营、REITs 盘活在推进。少数股东占约 26%。', '维持资本＝折旧×74%（约 152—163 亿元，归母口径）；扩张资本（城市更新、运营资产、存量 PPP 尾款，归母口径）2026 年 110、2027 年 100、2028 年 90、2029 年 80，2030 年起 70 亿元。', 'FCFE＝所有者收益−扩张资本＋净借款。', '逐年假设·维持/扩张资本', '2026—2035', '新的大额投资模式（如城市更新一二级联动）或年度投资活动净流出超过 400 亿元。', 'REITs、ABS 盘活带来的单年回流。', '城市更新回报周期 5—10 年，管理层自称“权宜之计”；若规模化，扩张资本会更高。', '已形成建议'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-DEBT', '净借款与债务成本', '带息负债 2025 年末 9,405 亿元、2026H1 9,498 亿元；财务费用（净额）÷平均带息负债约 1.96%；2026H1 综合融资成本 −14bp、利息费用 −9.8%，但汇兑损失使财务费用 +4.3%。', '净借款：2026 年 +200、2027 年 +110、2028 年 +40、2029 年 0、2030 年 −50、2031 年 −70、2032—2035 年 −80 亿元（2035 年约 9,315 亿元）。平均债务成本（按财务费用净额口径）2026 年 1.95%、2027 年 1.90%、2028 年起 1.85%。', '利息＝(期初＋期末)÷2×债务成本；2026—2028 年的净借款部分用于支付股息（见判断 J-PAYOUT 的现金检验）。', '逐年假设·净借款、平均债务成本', '2026—2035', '年报带息负债偏离 300 亿元以上；利率环境变化超过 50bp。', '季度续借。', '净借款是合并口径，少数股东那部分借款本不该全部计入股东现金；本模型净借款小，影响有限。', '已形成建议'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-PAYOUT', '派息率路径', '每股股息 2023—2025 年度约 0.2715 元，派息率 2018 年约 18%→2025 年 28.7%（约 +1.5pt/年）；管理层：2026 年度每股派息保持平稳；国资委市值管理、破净整改（2027 年底时限）。', '2026 年 31.44%（每股 0.2718 元不变、利润下降导致派息率上升），2027 年起每年 +1pt，2035 年 40%。理由：经营现金流在改善、扩张资本下降，2029 年起 FCFE 高于计划股息；终值按永续增长 1% 计，可持续派息率远高于 40%，40% 偏保守。', '股息＝归母净利×派息率。2026—2028 年 FCFE 刚好覆盖股息（含每年 40—200 亿元净借款）；之后有余。', '逐年假设·派息率', '2026—2035，全部情景', '年度分红方案；股东回报规划；派息率偏离假设 5pt 以上。', '单次特别分红或回购。', '若现金流不改善，公司可能维持每股股息但继续借钱支付；也可能为保住资产负债率而不提高派息。另一面：按本路径，留存的 60%—65% 利润几乎不带来利润增长，“资产与资本”页的 ROE 从 2026 年 7.2% 降到 2035 年 5.7%，低于资本成本——这正是 PB 0.37 倍的含义；派息率越高，股东价值越高。', '已形成建议'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-R', '折现率与风险溢价', '中债 10 年 1.64%（2026-10-21）。长江电力用 3.5% 风险溢价（类债资产），太阳纸业 6%（周期制造业）。中国建筑：资产负债率 77%、应收与 PPP 资产质量不透明、少数股东与永续债多层分配，但央企信用、业务分散、股息稳定。', '风险溢价 6.0%，基准折现率 7.6%；悲观 8.6%、乐观 7.1%。要求收益率（你自己的门槛）仍为 6%；无风险利率取高频数据里的中债 10 年期国债到期收益率（建模时 1.64%，2026-10-21），加风险溢价后按 0.1 个百分点四舍五入（7.64% → 7.6%）。', '折现率 +1pt，基准价值约 −0.7 元（见单参数试验与敏感性表）。', '估值模型·无风险利率、风险溢价；情景·折现率', '全部', '长期利率变化超过 0.5 个百分点；资产质量出现系统性问题。', '单日利率波动。', '风险溢价是判断，不是测量值；市场给的 PB 0.37 倍隐含的要求回报约 9%。', '已形成建议'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-TV', '终值与永续增长', '中国建筑业总量已过峰值（住宅新开工持续下降），增量来自城市更新、工业与能源工程、海外；模型 2029 年起收入 +1%/年。', '基准永续增长 1.0%（名义，略低于通胀，即实物量缓慢收缩）；悲观 0%、乐观 2%。', '终值＝终年股息×(1＋g)÷(r−g)，占价值约 57%；g 每 +0.5pt，价值约 +0.3 元。', '情景·永续增长率', '2035 年之后', '行业长期需求判断改变。', '—', '若地产与基建投资长期萎缩，名义增长可能为负。', '已形成建议'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-CB', '现金桥接其余项目', '权益法投资收益 2024—2025 年 36.5、17.1 亿元，2026H1 5.6 亿元；收到投资分红 2024—2025 年 25.7、21.7 亿元；货币资金 4,117 亿元。', '非现金收益扣除 8、收到投资分红 15、其他现金调整 0、最低现金补充 0（现金充足）。减值不在现金桥接里加回：视为应收款的真实损失。', '所有者收益＝归母净利＋归母折旧−非现金收益＋投资分红＋其他调整−营运资本增加−维持资本。', '逐年假设·非现金收益、投资分红、其他现金调整、最低现金补充', '2026—2035', '联营企业收益或分红大幅变化。', '季度波动。', '若减值事后被收回（转回），现金会比本模型多。', '已形成建议'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'J-REL', '相对估值对照（不进入模型）', 'PB 约 0.37 倍、PE 约 5 倍、股息率约 6%；卖方目标价 4.8—6.87 元；2026-07 本地研究的 PE＋PB＋DDM 加权中枢 5.27 元。', '相对估值只做对照：PB 0.37 倍说明市场不相信账面资产（应收、合同资产、PPP、地产存货）能按账面变现；绝对估值以股息贴现＋现金支持口径为准。', '—', '—（对照用）', '—', '—', '—', '若减值回落、ROE 回到 10%，PB 修复到 0.6 倍即对应约 7 元。', '研究规则');

INSERT INTO vi_lnk_judgment_facts (judgment_id, fact_id, "createdAt", "updatedAt")
SELECT j.id, f.id, now(), now() FROM (VALUES ('J-Q', '2025 年新签合同总额 45,458 亿元'), ('J-Q', '2026 年 1—9 月新签 32,890 亿元（−0.1%），房建新开工 −18.1%'), ('J-Q', '订单结构：工业厂房、能源、数据中心增长'), ('J-Q', '海外：订单高增但毛利率低'), ('J-P', '收入转化率从 0.54 降到 0.46，2026 年约 0.41'), ('J-P', '2026 年 1—9 月新签 32,890 亿元（−0.1%），房建新开工 −18.1%'), ('J-P', '2026 年上半年业绩：营收 −12%、归母 −24%'), ('J-P', '2026 年目标与管理层体感'), ('J-M', '核心利润率稳定在 6%—7%'), ('J-M', '毛利率：施工提升、地产下滑'), ('J-M', '2026 年上半年分业务：房建 −18%、地产 +15%、境外 +27%'), ('J-IMP', '减值：2025 年 258.7 亿元，2026 年上半年 100.4 亿元'), ('J-IMP', '减值构成：风险房企近半，地产存货与 PPP/BT 有上升苗头'), ('J-IMP', '应收账款＋合同资产 10,045 亿元，两年增长 70%'), ('J-DA', '资本开支约 260 亿元，投资性现金流出 300 亿元级'), ('J-TAX', '少数股东分走约 27% 的净利润'), ('J-WC', '经营现金流：连续六年为正但远低于利润'), ('J-WC', '应收账款＋合同资产 10,045 亿元，两年增长 70%'), ('J-WC', '化债回款：2025 年政府债权回收超 1,500 亿元'), ('J-WC', 'PPP：2023-11 后不再新增，存量权益投资 5,951 亿元'), ('J-CAPEX', '资本开支约 260 亿元，投资性现金流出 300 亿元级'), ('J-CAPEX', 'PPP：2023-11 后不再新增，存量权益投资 5,951 亿元'), ('J-DEBT', '带息负债 9,405 亿元，净负债 5,289 亿元'), ('J-PAYOUT', '分红：每股 0.2718 元、派息率 28.7%，2026 年度保持平稳'), ('J-PAYOUT', '控股股东增持 5—10 亿元，持股 57.73%'), ('J-TV', '2026 年目标与管理层体感'), ('J-CB', '经营现金流：连续六年为正但远低于利润'), ('J-REL', '估值：PB 0.37 倍、PE 约 5 倍、股息率约 6%'), ('J-REL', '卖方一致预期 2026—2028 年归母 370/382/392 亿元')) v(jc, ft)
JOIN vi_judgment_base j ON j.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND j.code = v.jc JOIN vi_fact_base f ON f.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND f.title = v.ft;

INSERT INTO vi_lnk_judgment_theses (judgment_id, thesis_id, "createdAt", "updatedAt")
SELECT j.id, t.id, now(), now() FROM (VALUES ('J-Q', 'T1'), ('J-P', 'T2'), ('J-M', 'T3'), ('J-IMP', 'T8'), ('J-IMP', 'T4'), ('J-IMP', 'T7'), ('J-DA', 'T5'), ('J-TAX', 'T6'), ('J-WC', 'T4'), ('J-CAPEX', 'T4'), ('J-CAPEX', 'T5'), ('J-DEBT', 'T5'), ('J-PAYOUT', 'T6'), ('J-PAYOUT', 'T7'), ('J-R', 'T8'), ('J-TV', 'T2'), ('J-CB', 'T4'), ('J-REL', 'T7')) v(jc, tc)
JOIN vi_judgment_base j ON j.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND j.code = v.jc JOIN vi_thesis_base t ON t.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND t.code = v.tc;

INSERT INTO vi_biz_model_base (company_id, code, element, title, content, metric, trend) VALUES
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B1', '客户细分', '政府与城投占四成以上，住宅降到两成以内，工业与能源业主在增加', '施工业务的业主：地方政府、城投与国企（政府背景业主占房建基建项目 40% 以上）；开发商（住宅占房建订单 20% 以内）；工业、能源、数据中心等产业业主（工业厂房占房建新签 33%、能源工程占基建新签 40%）；海外业主（订单不足 5%）。地产业务的客户是购房者，中海聚焦一二线核心城市。', '政府背景业主 >40%；住宅 <20%；工业厂房占房建 33%；海外 <5%', '风险房企应收是减值源头（T8）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B2', '价值主张', '房建、基建、勘察设计的总承包，加一块地产开发', '房屋建筑（住宅、公建、工业厂房、数据中心、超高层）、基础设施（市政、能源工程、交通、水务）、勘察设计；地产开发与投资（中海地产、中建地产）。卖点是别人干不了的大项目（超高层、复杂公建、大型工业厂房）、按期交付，以及能带着资金进场（M1、M2）；公司自称“规划设计、投资开发、基础设施建设、房屋建筑工程”四位一体。', '三大业务毛利率（2025）：房建 8.4%、基建 9.9%、地产 14.4%', '订单从住宅转向工业厂房、能源、数据中心（B1、B5）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B3', '渠道通路', '招投标为主，过去靠投资（PPP）带动施工，现在靠选项目', '工程项目主要靠公开招投标，大项目看资质、业绩和融资能力（M1、M2）；2023 年 11 月前用 PPP 等投资带动施工总包，之后不再新增 PPP，转向城市更新、投建营一体化与海外；“两优两重”选项目（M4）。', '2026H1 新接项目毛利率 +0.2pt；建筑市场占有率 +2.2pt（管理层）', '投资带动施工的模式在收缩（伪壁垒 M7），订单质量取决于选项目的纪律（T1、T3）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B4', '客户关系', '项目制：一次招投标、一份合同，按节点收款', '与业主是项目制关系：按合同施工、按进度确认收入、按节点付款、质保金后付（资金占用见 B9）。与地方政府、城投的长期关系能带来项目信息与准入，但不带来定价权，也不保证回款（伪壁垒 M6）。地产业务面对购房者，靠品牌、产品与交付（M3）。', '政府背景业主占四成以上，化债力度较去年减弱（管理层）', '业主的付款能力决定现金回收（T4）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B5', '收入来源', '新签合同×收入转化率：房建约六成，订单变收入在变慢', '收入＝新签合同总额×收入转化率（2025 年 45,458 亿元×0.458），施工按进度确认收入。2025 年收入：房建 12,342 亿元（59%）、基建 5,432 亿元（26%）、地产 2,844 亿元（14%）、勘察设计约 1%；境外 1,417 亿元（约 7%）。地产收入只占约 15%，却贡献约 34% 的分部利润总额（2026 年上半年，事实摘录）。周期：全国建筑业新签合同额连续三年下降、总产值 2025 年近十年首次下降；公司新签 2023—2025 年稳定在 4.3—4.5 万亿元（份额上升，T1），但订单变成收入的速度在变慢（收入转化率 0.54 → 0.46，原因与前景见 T2）。增量：工业厂房、能源工程、数据中心、城市更新（含中国建筑国际旗下中建海龙的模块化建筑 MiC）、海外（订单高增、毛利率低）。地产随销售周期，合约销售连续三年下降（事实摘录）。', '2025 年营收 20,821 亿元；新签 +1.0%、收入 −4.8%；2026 年 1—9 月新签 −0.1%、房建新开工 −18.1%；地产收入占约 15%、利润总额占约 34%（2026H1）', '收入转化率在降，收入能否在 2027 年见底，是经营模型最大的问题（T2）；房建收入 2026 年上半年 −18%；地产利润占比高，意味着中国建筑的估值有一部分是地产股（M3、T8）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B6', '核心资源', '央企信用与资质、全国与海外施工网络、两个港股平台', '央企信用与低成本资金（M1）；资质、业绩与超大复杂项目的总承包能力（M2）；施工网络覆盖全国与海外近百个国家和地区；持股中国海外发展（中海地产）56.1%、中国建筑国际（含中建海龙）61.8%；中建财务公司。', '评级 A/A2/A；平均债务成本约 1.96%；中海权益销售 2025 年行业第一', '信用优势让它在下行期拿份额，也让它更愿意垫资（T1、T4）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B7', '关键业务', '拿项目、组织分包、垫资和承担风险', '大部分工作量交给分包与劳务（B8、B9），公司的价值在拿项目、组织管理、垫资和承担风险：投标与选项目（“两优两重”，M4）、总包管理与成本管控、设计施工一体化；地产业务的拿地、开发与销售由中海地产等平台运营（M3）。', '分包＋原材料＋劳务约占成本与费用 73%', '能不能把毛利守住，看选项目与成本管控是否真的有效（M4 待验证）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B8', '重要合作', '控股股东中建集团、分包与供应商、子公司的少数股东', '控股股东中建集团持股 57.73%。分包商、材料供应商与劳务队伍承担大部分施工量，回款慢的压力一部分传给他们（应付票据及账款 2023 年 7,007 亿元 → 2025 年 10,091 亿元，V1）。中海地产、中国建筑国际等子公司有外部股东，少数股东分走约 27% 的净利润（T6）。', '控股股东持股 57.73%；少数股东分走约 27% 的净利润', '分包与供应商的承受力是垫资模式的边界（V1）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B9', '成本结构', '分包、材料、劳务占七成以上，归母只剩收入的约 2%；利润沉淀在应收里', '2025 年成本与费用（19,630 亿元）里分包约 37%、原材料约 24%、劳务约 12%，其余是地产结转、其他施工成本与职工薪酬（事实摘录）。施工毛利 8%—11%，扣掉费用后核心利润率约 6.2%（不含减值）。每 100 元收入：营业成本 90.1 元、税金 0.4 元、销售管理研发费用 4.2 元、财务费用 0.85 元、减值 1.24 元（约收入的 1.2%），利润总额 3.4 元；所得税 0.8 元、少数股东 0.7 元，归母净利 1.9 元（2019 年 3.0 元）；即归母净利≈利润总额×56%（税 24%、少数股东 26%）。资本：先垫资后收款——业主按节点付款、质保金后付，回款慢于确认；每 1 元收入对应的应收账款＋合同资产从 2019 年 0.21 元、2023 年 0.26 元升到 2025 年 0.48 元。经营现金流长期只有利润的一到五成（事实摘录）；PPP 存量权益投资 5,951 亿元。购建长期资产约 260 亿元/年，真正的资本需求是营运资本。', '2025 年：毛利率 9.9%、核心利润率 6.2%、归母净利 390.7 亿元、归母净利率 1.9%（2019 年 3.0%）；经营现金流 205.4 亿元；应收＋合同资产 10,045 亿元（÷收入 0.48，2019 年 0.21）', '收入大、利润薄，利润对利润率极其敏感（J-M）；利润率变薄主要来自减值与少数股东，减值在升（T8）；收入下降时费用刚性（2026H1 期间费用率 +0.44pt，T3）；资本占用翻倍来自回款变慢，化债回款能否让营运资本占用逐年下降（T4、J-WC）。');

INSERT INTO vi_lnk_biz_model_facts (biz_model_id, fact_id, "createdAt", "updatedAt")
SELECT x.id, y.id, now(), now() FROM (VALUES ('B1', '客户结构：政府背景业主占四成以上，住宅占房建订单两成以内'), ('B1', '订单结构：工业厂房、能源、数据中心增长'), ('B1', '海外：订单高增但毛利率低'), ('B2', '全球最大承包商：ENR 第一、评级 A/A2/A、承建国内绝大多数 300 米以上超高层'), ('B2', '订单结构：工业厂房、能源、数据中心增长'), ('B3', 'PPP：2023-11 后不再新增，存量权益投资 5,951 亿元'), ('B3', '市场份额：建筑新签约占全国 13.2%，八大央企合计约 47%'), ('B4', '客户结构：政府背景业主占四成以上，住宅占房建订单两成以内'), ('B5', '2025 年新签合同总额 45,458 亿元'), ('B5', '核心利润率稳定在 6%—7%'), ('B5', '少数股东分走约 27% 的净利润'), ('B5', '地产贡献约三分之一利润总额'), ('B5', '2026 年上半年分业务：房建 −18%、地产 +15%、境外 +27%'), ('B5', '市场份额：建筑新签约占全国 13.2%，八大央企合计约 47%'), ('B5', '收入转化率从 0.54 降到 0.46，2026 年约 0.41'), ('B5', '2026 年 1—9 月新签 32,890 亿元（−0.1%），房建新开工 −18.1%'), ('B5', '地产：销售面积大降，均价上升，土储收缩'), ('B6', '全球最大承包商：ENR 第一、评级 A/A2/A、承建国内绝大多数 300 米以上超高层'), ('B6', '带息负债 9,405 亿元，净负债 5,289 亿元'), ('B6', '少数股东分走约 27% 的净利润'), ('B6', '中国海外发展 2025 年：毛利率 15.5%，股东应占溢利 126.9 亿元'), ('B6', '控股股东增持 5—10 亿元，持股 57.73%'), ('B7', '成本构成：分包 37%、原材料 24%、劳务 12%'), ('B7', '毛利率：施工提升、地产下滑'), ('B8', '全球最大承包商：ENR 第一、评级 A/A2/A、承建国内绝大多数 300 米以上超高层'), ('B8', '带息负债 9,405 亿元，净负债 5,289 亿元'), ('B8', '少数股东分走约 27% 的净利润'), ('B8', '中国海外发展 2025 年：毛利率 15.5%，股东应占溢利 126.9 亿元'), ('B8', '控股股东增持 5—10 亿元，持股 57.73%'), ('B9', '2025 年新签合同总额 45,458 亿元'), ('B9', '核心利润率稳定在 6%—7%'), ('B9', '少数股东分走约 27% 的净利润'), ('B9', '成本构成：分包 37%、原材料 24%、劳务 12%'), ('B9', '毛利率：施工提升、地产下滑'), ('B9', '应收账款＋合同资产 10,045 亿元，两年增长 70%'), ('B9', '经营现金流：连续六年为正但远低于利润'), ('B9', 'PPP：2023-11 后不再新增，存量权益投资 5,951 亿元'), ('B9', '资本开支约 260 亿元，投资性现金流出 300 亿元级')) v(k1, k2)
JOIN vi_biz_model_base x ON x.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND x.code = v.k1 JOIN vi_fact_base y ON y.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND y.title = v.k2;

INSERT INTO vi_value_chain_base (company_id, code, position, participant, role, force, power, effect, trend, profit_share, analysis, counter) VALUES
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'V1', '上游供给', '专业分包商与劳务队伍', '专业分包、劳务', '供应商议价能力', '弱', '有利', '稳定', '分包＋劳务约 9,569 亿元，占成本与费用约 49%', '分包与劳务高度分散，总包方掌握定价与付款节奏；回款慢的压力很大部分传给了分包和供应商（应付票据及账款 2026 年 6 月末 11,104 亿元）。', '拖欠分包有监管与社会成本（农民工工资支付等），供应链压力过大时会影响履约与质量；这部分“免费融资”迟早要还（T4 反方）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'V2', '上游供给', '钢材、水泥、混凝土等建材供应商；钢结构厂商（鸿路钢构等）', '原材料与构件', '供应商议价能力', '弱', '中性', '稳定', '原材料 4,671 亿元，约占成本与费用 24%', '建材是大宗品，价格随周期波动；公司集采规模大，合同多有调价条款但不完全。工业厂房的钢结构依赖专业厂商（鸿路钢构产能 520 万吨）。', '建材涨价时固定总价合同会挤压毛利；钢结构龙头的规模与自动化在提升议价力。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'V3', '本公司环节', '中国建筑：总承包（设计—采购—施工—投资—运营）', '拿项目、组织管理、垫资、承担风险', '不适用', '中', '中性', '稳定', '施工业务毛利率 8.8%（2025）', '价值在“拿项目＋管项目＋垫资”：靠规模、资质与信用拿到大项目（M1、M2），靠项目管理把毛利守在 8%—10%（M4），靠资产负债表垫付业主的欠款（B9）。', '垫资能力就是风险承担能力：规模越大，应收与减值越多（T4、T8）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'V4', '下游客户', '地方政府、城投与国有业主', '房建、基建工程', '买方议价能力', '强', '不利', '稳定', '政府背景业主占四成以上（B1）', '业主决定付款节奏与结算条件，地方财政紧张时拖欠是常态；2024 年 11 月起的化债让一部分欠款收回（论证见 T4）。', '央企债权在化债中优先级较高，政府债权的最终损失可能不大，主要是时间价值（T4 正方）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'V5', '下游客户', '房地产开发商（住宅总包）', '住宅施工', '买方议价能力', '中', '不利', '减弱', '住宅占房建订单 20% 以内', '住宅开工持续下降（房建新开工 2026 年 1—9 月 −18.1%）；风险房企（恒大、碧桂园、融创等）应收是 2025 年专项减值的近一半，公司已主动压缩住宅订单。', '风险房企计提高峰已过（管理层，T8）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'V6', '下游客户', '工业、能源、数据中心等产业业主', '工业厂房、能源工程、数据中心', '买方议价能力', '中', '有利', '增强', '工业厂房约占房建新签三分之一、能源工程约占基建新签四成（2025）', '资金方更可靠、付款条件较好，是订单结构优化的方向；数据中心与算力中心 2026 年上半年新签 873 亿元（+328%）。', '产业投资有周期（光伏、锂电产能过剩），部分业主是民企，付款风险并不低；中铁、铁建、中冶、电建也在抢这块（V8）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'V7', '下游客户', '购房者（地产业务）', '商品住宅', '买方议价能力', '强', '不利', '稳定', '地产收入约占 14%、利润总额约占 34%', '全国新建商品房销售额 2025 年 −12.6%；中海聚焦一二线核心城市，销售优于同业（M3）；均价上升、面积大降（2026 年上半年面积 −25.8%）。', '核心城市房价若继续下跌，2021—2023 年拿的高价地会持续计提（T8）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'V8', '同业竞争', '建筑央企（中铁、铁建、交建、电建、中冶）与地方建工集团（上海建工等）', '同类工程', '行业内竞争', '强', '不利', '稳定', '八大建筑央企新签占全国约 47%（2024）', '行业总量下行，民企与弱地方国企退出，央企集中度上升；但央企之间同质化竞争激烈，毛利率都在 9%—12%；铁路、交通、水电等细分领域有专业龙头（中铁、铁建、交建、电建），中国建筑强在房建、超高层与工业厂房。', '集中度提升后竞争可能更理性：公司新接项目毛利率 +0.2pt（T3）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'V9', '替代品', '装配式与模块化建造（MiC）、钢结构住宅、代建', '建造方式的替代', '替代品威胁', '弱', '中性', '增强', '—', '建筑本身没有替代品，替代的是建造方式：装配式、模块化（中国建筑国际旗下中建海龙是 MiC 龙头）与代建（轻资产）。公司自己就是新方式的领先者，威胁弱。', '钢结构住宅路线（鸿路钢构、精工钢构）与混凝土 MiC 竞争；代建降低资本需求，也压低利润率。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'V10', '潜在进入者', '新进入者：资质、业绩与资金门槛', '新增供给', '新进入者威胁', '弱', '有利', '减弱', '—', '特级资质、大项目业绩、融资能力是门槛；下行期是在“退出”而不是“进入”：全国建筑业从业人数 2025 年 −12.97%。', '地方国资平台与城投下属的建设公司可能在本地截留项目。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'V11', '监管', '国资委、财政部、住建部与地方政府', '考核、化债、资质与地产调控', '不适用', '强', '中性', '增强', '—', '国资委考核利润、经营现金流、资产负债率与 ROE，推动市值管理与“破净”整改（T6）；财政部化债决定回款（T4）；住建部管资质与安全；地产调控决定住宅需求。', '政策目标不一定与股东回报一致：稳增长任务、保交楼、化债配合（T6 反方）。');

INSERT INTO vi_lnk_value_chain_facts (value_chain_id, fact_id, "createdAt", "updatedAt")
SELECT x.id, y.id, now(), now() FROM (VALUES ('V1', '成本构成：分包 37%、原材料 24%、劳务 12%'), ('V1', '应收账款＋合同资产 10,045 亿元，两年增长 70%'), ('V2', '成本构成：分包 37%、原材料 24%、劳务 12%'), ('V3', '毛利率：施工提升、地产下滑'), ('V4', '客户结构：政府背景业主占四成以上，住宅占房建订单两成以内'), ('V4', '化债回款：2025 年政府债权回收超 1,500 亿元'), ('V5', '减值构成：风险房企近半，地产存货与 PPP/BT 有上升苗头'), ('V5', '2026 年 1—9 月新签 32,890 亿元（−0.1%），房建新开工 −18.1%'), ('V6', '订单结构：工业厂房、能源、数据中心增长'), ('V7', '地产同业 2025 年：中海权益销售第一，保利归母仅 10 亿元'), ('V7', '地产：销售面积大降，均价上升，土储收缩'), ('V7', '地产贡献约三分之一利润总额'), ('V8', '市场份额：建筑新签约占全国 13.2%，八大央企合计约 47%'), ('V8', '建筑央企 2025 年：毛利率都在 9%—12%，减值÷收入 0.8%—1.3%'), ('V10', '市场份额：建筑新签约占全国 13.2%，八大央企合计约 47%'), ('V11', '化债回款：2025 年政府债权回收超 1,500 亿元'), ('V11', '分红：每股 0.2718 元、派息率 28.7%，2026 年度保持平稳')) v(k1, k2)
JOIN vi_value_chain_base x ON x.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND x.code = v.k1 JOIN vi_fact_base y ON y.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND y.title = v.k2;

INSERT INTO vi_competitor_base (company_id, name, ticker, relation, segment, scale_label, scale_value, scale_unit, paying_rate, price_point, gross_margin, growth, as_of, strategy, vs_us, threat, trend, source_id) VALUES
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '中国中铁', '601390.SH', '直接竞争', '铁路、公路、市政与房建', '营业收入', 10906, '亿元', NULL, NULL, 0.093, -0.058, '2025-12-31', '铁路建设份额约 45%（与中国铁建合计约九成）；市政建设约占营收 44%，市政与房建同中国建筑正面竞争；旗下中铁资源有 5 座矿山（2025 年产铜约 30 万吨），矿产是第二利润来源。', '收入约为中国建筑的一半，毛利率、ROE、PB 都低于中国建筑；没有大地产平台，利润更“纯工程”：减值÷收入与少数股东占比都明显更低（同业见事实摘录）。', '中', '下降', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND title = '岗底斯：建筑央企 2025 年年报利润表与同业对比（2026-10-23）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '中国铁建', '601186.SH', '直接竞争', '铁路、公路、轨道交通、房建', '营业收入', 10298, '亿元', NULL, NULL, 0.097, NULL, '2025-12-31', '与中国中铁平分铁路建设市场，川藏、新藏铁路等超级工程储备；工程承包约占营收 89%，在房建中低端项目上与中国建筑同质化竞争；布局“六张网”等新领域。', '盈利能力弱于中国建筑（ROE 5.4%、PB 0.30 倍）；地产开发规模小（2025 年权益销售排名第 11），没有中海这样的地产平台。', '中', '下降', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND title = '岗底斯：建筑央企 2025 年年报利润表与同业对比（2026-10-23）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '中国交建', '601800.SH', '直接竞争', '港口、公路、桥梁、城市综合开发', '营业收入', 7311, '亿元', NULL, NULL, 0.114, NULL, '2025-12-31', '交通基建龙头（港口、公路份额第一），参与平陆运河等运河项目；基建约占营收 88%；两金压降较好（2026 年一季度两金约占资产 57%）。2026 年上半年新签 9,029 亿元。', '毛利率更高，但 ROE 只有 4.7%，少数股东与减值的拖累和中国建筑相近；在交通基建上比中国建筑专业。', '中', '稳定', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND title = '岗底斯：建筑央企 2025 年年报利润表与同业对比（2026-10-23）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '中国电建', '601669.SH', '直接竞争', '水电、抽水蓄能、新能源工程', '营业收入', 6456, '亿元', NULL, NULL, 0.124, NULL, '2025-12-31', '承担国内 65% 以上大中型水电站施工，抽水蓄能勘察设计约 90%；控股并网装机 4,014 万千瓦（2025），运营电站提供稳定现金流。', '在中国建筑发力的能源工程上更专业、毛利率更高；持有运营电站，商业模式不同，PB 高于中国建筑。', '中', '上升', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND title = '岗底斯：建筑央企 2025 年年报利润表与同业对比（2026-10-23）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '中国中冶', '601618.SH', '直接竞争', '冶金与工业厂房、房建、市政', '营业收入', 4554, '亿元', NULL, NULL, 0.101, NULL, '2025-12-31', '冶金建设龙头，转向工业厂房、城市更新与矿产资源；2026 年上半年新签 4,136 亿元（−24.5%）。', '2025 年资产与信用减值约为收入的 6%，归母只剩 13.2 亿元：减值失控的反面样本（T8）；在冶金与重工业厂房上与中国建筑竞争。', '低', '下降', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND title = '岗底斯：建筑央企 2025 年年报利润表与同业对比（2026-10-23）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '上海建工', '600170.SH', '直接竞争', '上海及华东房建、城市更新', '营业收入', 2060, '亿元', NULL, NULL, 0.103, NULL, '2025-12-31', '地方建工龙头，深度绑定上海（政府与国企类项目约 80%）；城市更新等新兴业务约占新签 26%。安徽建工等省属建工集团的打法类似：深耕本省。', '毛利率与中国建筑相近，但 ROE 只有 2.5%：规模、信用与业务分布都不如中国建筑。', '低', '稳定', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND title = '岗底斯：建筑央企 2025 年年报利润表与同业对比（2026-10-23）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '保利发展', '600048.SH', '直接竞争', '房地产开发（中海地产的同业）', '权益销售额', 2000, '亿元', NULL, NULL, 0.128, -0.217, '2025-12-31', '央企地产龙头之一，2025 年全口径销售 2,530 亿元，2026 年 1—5 月继续下降。', '同为央企，2025 年计提大额存货减值后归母只剩约 10 亿元，盈利远弱于中海（M3）。', '中', '下降', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND title = '岗底斯：地产同业销售排名与 2025 年业绩（克而瑞、中指院、公司公告）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '华润置地', '01109.HK', '直接竞争', '房地产开发＋购物中心运营', '权益销售额', 1593, '亿元', NULL, NULL, 0.212, -0.105, '2025-12-31', '开发、经营性不动产（购物中心）、轻资产管理三条曲线；融资成本 2.72%。', '开发结算毛利率与中海相同，但有中海缺少的大规模持有型商业（收租毛利率约 72%），利润更稳；中海在纯开发的规模与利润率上领先。', '中', '稳定', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND title = '岗底斯：地产同业销售排名与 2025 年业绩（克而瑞、中指院、公司公告）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '鸿路钢构', '002541.SZ', '上游', '钢结构制造（工业厂房核心供应商）', '钢结构产能', 520, '万吨', NULL, NULL, NULL, NULL, '2025-12-31', '国内钢结构制造龙头，下游七成以上是工业厂房（锂电、存储、晶圆、数据中心）；约 3,000 台焊接机器人降本；也走钢结构住宅路线。', '不与中国建筑争总包，是工业厂房的上游供应商：它的价格与产能影响中国建筑工业厂房的成本（V2）；钢结构住宅与中建海龙的混凝土 MiC 是竞争路线（V9）。ROE 6.3%、PB 1.56 倍。', '低', '上升', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND title = '岗底斯：建筑央企 2025 年年报利润表与同业对比（2026-10-23）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '万喜（VINCI）', 'DG.PA', '海外对标', '建筑＋特许经营（高速公路、机场）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-31', '欧洲建筑与特许经营集团：施工之外持有高速公路、机场等特许经营资产，重利润率而非业务量。', '利润主要来自有定价权的特许经营资产；中国建筑的 PPP 回报由政府付费，本质是对地方政府的长期债权（伪壁垒 M7）。海外市场上是对手，但中国建筑海外订单不足 5%。', '低', '稳定', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND title = '岗底斯：建筑央企 2025 年年报利润表与同业对比（2026-10-23）' LIMIT 1));

INSERT INTO vi_lnk_competitor_facts (competitor_id, fact_id, "createdAt", "updatedAt")
SELECT x.id, y.id, now(), now() FROM (VALUES ('中国中铁', '建筑央企 2025 年：毛利率都在 9%—12%，减值÷收入 0.8%—1.3%'), ('中国铁建', '建筑央企 2025 年：毛利率都在 9%—12%，减值÷收入 0.8%—1.3%'), ('中国交建', '建筑央企 2025 年：毛利率都在 9%—12%，减值÷收入 0.8%—1.3%'), ('中国电建', '建筑央企 2025 年：毛利率都在 9%—12%，减值÷收入 0.8%—1.3%'), ('中国中冶', '建筑央企 2025 年：毛利率都在 9%—12%，减值÷收入 0.8%—1.3%'), ('上海建工', '建筑央企 2025 年：毛利率都在 9%—12%，减值÷收入 0.8%—1.3%'), ('保利发展', '地产同业 2025 年：中海权益销售第一，保利归母仅 10 亿元'), ('华润置地', '地产同业 2025 年：中海权益销售第一，保利归母仅 10 亿元'), ('华润置地', '中国海外发展 2025 年：毛利率 15.5%，股东应占溢利 126.9 亿元')) v(k1, k2)
JOIN vi_competitor_base x ON x.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND x.name = v.k1 JOIN vi_fact_base y ON y.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND y.title = v.k2;

INSERT INTO vi_lnk_value_chain_competitors (value_chain_id, competitor_id, "createdAt", "updatedAt")
SELECT x.id, y.id, now(), now() FROM (VALUES ('V2', '鸿路钢构'), ('V6', '中国中冶'), ('V6', '中国电建'), ('V7', '保利发展'), ('V7', '华润置地'), ('V8', '中国中铁'), ('V8', '中国铁建'), ('V8', '中国交建'), ('V8', '中国电建'), ('V8', '中国中冶'), ('V8', '上海建工'), ('V9', '鸿路钢构')) v(k1, k2)
JOIN vi_value_chain_base x ON x.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND x.code = v.k1 JOIN vi_competitor_base y ON y.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND y.name = v.k2;

INSERT INTO vi_moat_base (company_id, code, title, moat_type, verdict, strength, trend, mechanism, financial_link, evidence, counter, replication, threats, check_metric, check_op, check_threshold, check_years) VALUES
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'M1', '央企信用与低成本资金', '成本优势', '局部优势', '中', '稳定', '三大评级 A 级（全球建筑行业最高）、带息负债平均成本约 2%：业主缺钱的下行期，能垫资、能做投资带动施工的总包商拿到更多项目，民企与弱地方国企在退出。', '体现在份额（数字见 T1）；没有体现在利润率：毛利率 9.9%，与央企同业（9.3%—12.4%）持平。', '八大央企合计占全国新签的比重从 2013 年约 24% 升到 2024 年约 47%；下行期退出的是民企与弱地方国企（V8、V10）。', '另外七家央企有同样的信用；信用优势被用来承担更多应收与 PPP（论证见 T1、T4）。', '央企身份与评级不可复制，但同级别央企都有；对民企与地方国企是很高的门槛。对照对手：中国中铁、中国铁建、上海建工。', '地方财政恶化拖累回款；国资委对资产负债率与现金流的约束；评级下调。', NULL, NULL, NULL, NULL),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'M2', '规模、资质与超大复杂项目的总承包能力', '工艺与组织', '局部优势', '中', '稳定', 'ENR 全球最大承包商，国内绝大多数 300 米以上超高层由公司承建；复杂公建、大型工业厂房、数据中心需要设计—采购—施工一体化与大项目管理经验，有资格和业绩竞标的企业少。', '订单向工业厂房（2025 年 +23%）、能源工程（+17%）、数据中心（2026 年上半年 +328%）转移；施工毛利率 2025 年 8.8%（+0.7pt）。', '行业下行期新签总量稳住（2026 年 1—9 月 −0.1%），同期中铁、铁建、交建上半年新签 −9.3%、−16.9%、−8.9%（岗底斯同业对比）。', '大项目同样低毛利、长账期；中铁、铁建、中冶、电建都在抢工业与能源工程（V8）。', '业绩、人才与项目经验要多年积累；央企同业在各自擅长的领域同样具备。', '产业投资周期（光伏、锂电过剩）；业主压价。', NULL, NULL, NULL, NULL),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'M3', '中海地产的拿地纪律、成本与品牌', '成本优势', '局部优势', '中', '稳定', '聚焦一二线核心城市、高权益比例拿地、费用率与融资成本处于行业最低区间：下行期销售跌幅小于同业，2025 年权益销售额行业第一。', '中国海外发展 2025 年毛利率 15.5%、股东应占溢利 126.9 亿元，而保利发展毛利率 12.8%、归母约 10 亿元；地产约占中国建筑利润总额的三分之一（B5）。', '2026 年 1—5 月中海全口径销售 +14.0%、保利 −9.3%；已售未结转约 1,805 亿元，毛利率约 18.4%。', '是“比同业好”，不是“不受周期影响”：毛利率从 17.7% 降到 15.5%、股东应占溢利 −18.8%；2021—2023 年的高价地仍有减值风险（T8）；中国建筑只持有 56.1%。', '拿地纪律与品牌要长期积累；华润置地在开发上同样优秀，还有持有型商业。', '核心城市房价继续下跌；土储收缩（期末 6,336 万㎡，2024 年末 7,718 万㎡）。', NULL, NULL, NULL, NULL),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'M4', '选项目与成本管控（“两优两重”）', '工艺与组织', '待验证', '弱', '增强', '主动选项目（优质业主、优质区域、重点领域、重大项目），治理负效项目、成本对标与集采，把毛利率守在约 10%。', '毛利率三年稳定在约 9.9%，2026 年上半年升到 10.3%；新接项目毛利率 +0.2pt（事实摘录）。', '收入下降时毛利率反而上升：2026 年上半年房建 8.2%（+0.9pt）、基建 10.8%（+0.5pt）。', '只有一年半的数据，提升未必可持续，费用也摊不薄（论证见 T3）。', '组织能力，但央企同业也在做同样的“提质增效”。对照对手：中国中铁、中国交建。', '竞争加剧、业主压价。', NULL, NULL, NULL, NULL),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'M5', '伪壁垒：新签合同额规模（4.5 万亿元）', '规模经济', '伪壁垒', '无', '削弱', '订单大看起来是护城河和收入保障，但签约口径包括框架协议和分期确认的大项目，订单的含金量会变。', '—（收入转化率 2021 年约 0.54 → 2025 年 0.46 → 2026 年约 0.41）', '新签 2023—2025 年 4.3—4.5 万亿元，收入却从 2.27 万亿元降到 2.08 万亿元（T2）。', '订单规模确实是收入的前提（已计入 M1、M2）。', '—', '—', NULL, NULL, NULL, NULL),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'M6', '伪壁垒：与地方政府、城投的客户关系', '生态与渠道', '伪壁垒', '无', '削弱', '与地方政府、城投的长期合作看起来是稳定的客户关系，但这类客户恰恰回款最慢。', '应收＋合同资产两年增长 70%；政府逾期债权要靠化债才能减少（2025 年约 1,500 亿元）。', '政府与城投是第一大客户群（B1）；管理层：化债力度较去年减弱。', '央企债权在化债中优先级高，最终损失可能不大（论证见 T4）。', '—', '地方财政继续收紧。', NULL, NULL, NULL, NULL),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'M7', '伪壁垒：PPP 与投资带动施工', '牌照与资源', '伪壁垒', '无', '削弱', '用投资换施工总包，看起来锁定了订单和长期收益，但回报主要由政府付费：本质是对地方政府的长期债权，回报低、周期长。', 'PPP 权益投资 5,951 亿元，累计回款 1,515 亿元；资产负债表上 PPP 相关的长期资产约 4,900 亿元（事实摘录）。', '2023 年 11 月后不再新增；与万喜的特许经营（有定价权的高速公路、机场）不同。', '存量 85.6% 已进入运营，2025 年投资回款 3,848 亿元、收支比 113.6%（T4）。', '—', '地方财政的付费能力。', NULL, NULL, NULL, NULL);

INSERT INTO vi_lnk_moat_facts (moat_id, fact_id, "createdAt", "updatedAt")
SELECT x.id, y.id, now(), now() FROM (VALUES ('M1', '全球最大承包商：ENR 第一、评级 A/A2/A、承建国内绝大多数 300 米以上超高层'), ('M1', '市场份额：建筑新签约占全国 13.2%，八大央企合计约 47%'), ('M1', '带息负债 9,405 亿元，净负债 5,289 亿元'), ('M1', '建筑央企 2025 年：毛利率都在 9%—12%，减值÷收入 0.8%—1.3%'), ('M2', '全球最大承包商：ENR 第一、评级 A/A2/A、承建国内绝大多数 300 米以上超高层'), ('M2', '订单结构：工业厂房、能源、数据中心增长'), ('M2', '毛利率：施工提升、地产下滑'), ('M3', '中国海外发展 2025 年：毛利率 15.5%，股东应占溢利 126.9 亿元'), ('M3', '地产同业 2025 年：中海权益销售第一，保利归母仅 10 亿元'), ('M3', '地产贡献约三分之一利润总额'), ('M3', '地产：销售面积大降，均价上升，土储收缩'), ('M4', '毛利率：施工提升、地产下滑'), ('M4', '核心利润率稳定在 6%—7%'), ('M5', '收入转化率从 0.54 降到 0.46，2026 年约 0.41'), ('M5', '2025 年新签合同总额 45,458 亿元'), ('M6', '客户结构：政府背景业主占四成以上，住宅占房建订单两成以内'), ('M6', '化债回款：2025 年政府债权回收超 1,500 亿元'), ('M7', 'PPP：2023-11 后不再新增，存量权益投资 5,951 亿元'), ('M7', '应收账款＋合同资产 10,045 亿元，两年增长 70%')) v(k1, k2)
JOIN vi_moat_base x ON x.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND x.code = v.k1 JOIN vi_fact_base y ON y.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND y.title = v.k2;

INSERT INTO vi_lnk_moat_theses (moat_id, thesis_id, "createdAt", "updatedAt")
SELECT x.id, y.id, now(), now() FROM (VALUES ('M1', 'T1'), ('M1', 'T4'), ('M2', 'T1'), ('M2', 'T3'), ('M3', 'T3'), ('M3', 'T8'), ('M4', 'T3'), ('M5', 'T2'), ('M6', 'T4'), ('M7', 'T4')) v(k1, k2)
JOIN vi_moat_base x ON x.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND x.code = v.k1 JOIN vi_thesis_base y ON y.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND y.code = v.k2;

INSERT INTO vi_fit_score_base (company_id, dimension, score, rationale, counter, sort) VALUES
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '长坡', 1, '建筑业总量已过峰（B5）；模型假设收入 2027 年见底、之后每年 +1%。', '城市更新、工业与能源工程、海外是长期需求；份额还在提升（T1）。', 1),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '厚雪', 1, '利润池薄：毛利率约 10%、归母净利率约 1.9%；建筑央企 ROE 只有 4.7%—7.9%（同业见事实摘录）。', '收入 2 万亿元、利润绝对额约 390 亿元；地产业务利润率更高（M3）。', 2),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '慢变', 3, '施工技术与行业格局变化慢，竞争规则清楚。', '政策（化债、地产调控、国资委考核）变化快，对现金流影响大（V11）。', 3),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '护城河', 2, '信用、规模与资质、中海的拿地纪律是局部优势，带来份额（M1—M3）。', '没有转化成高于同业的利润率，也没有高于资本成本的 ROE；新签规模、政府关系、PPP 是伪壁垒（M5—M7）。', 4),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '再投资', 1, '留存利润回报低：ROE 从 2021 年约 16.5% 降到 2025 年约 8.3%，留存的约 70% 利润主要沉淀为应收、合同资产与 PPP。', 'PPP 不再新增、资本开支下降；若减值回落，ROE 可回到 9%—10%（T7 正方）。', 5),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '财务质量', 1, '利润的现金含量低（B9），应收＋合同资产超过 1 万亿元，减值六年上升，少数股东与永续债多层分配。', '经营现金流连续六年为正、三年改善；化债回款在推进（T4）。', 6),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '治理配置', 3, '控股股东 8 次增持、无减持；每股股息不降、派息率逐年上升；国资委推动市值管理（T6）。', '央企目标函数兼顾稳增长与政策任务；少数股东分走约 27%。', 7),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '可估值性', 3, '业务清楚、历史数据完整、股息稳定，可以用 DDM＋现金桥接。', '应收、PPP、地产存货的真实价值不透明（PB 0.37 倍的原因），减值是最大的估计误差（T8）。', 8);

INSERT INTO vi_lnk_fit_score_theses (fit_score_id, thesis_id, "createdAt", "updatedAt")
SELECT x.id, y.id, now(), now() FROM (VALUES ('长坡', 'T2'), ('长坡', 'T1'), ('厚雪', 'T3'), ('厚雪', 'T7'), ('慢变', 'T1'), ('护城河', 'T1'), ('护城河', 'T7'), ('再投资', 'T7'), ('再投资', 'T4'), ('财务质量', 'T4'), ('财务质量', 'T8'), ('治理配置', 'T6'), ('可估值性', 'T8'), ('可估值性', 'T4')) v(k1, k2)
