INSERT INTO vi_change_log_base (company_id, change_date, title, target, old_value, new_value, reason, basis, verification) VALUES
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '2026-07-27', '首次深度研究（本地报告与 Excel）', '全部', '—', 'PE 45%＋PB 40%＋DDM 15% 加权：基准 5.31 元（2026-08-04 调为 5.27 元），三情景 3.78—6.80 元；结论“观察，安全边际不足”', '建立研究档案', '2023、2025 年年报，2026Q1 报告，统计局与财政部数据，两份卖方点评', '本地 Excel 与 HTML 报告的质量检查（见 01_过程代码/03_质量检查）'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '2026-10-22', '纳入价值投资框架（独立项目）', '公司、论点、事实、判断、历史财务、估值模型、跟踪', '本地持续投研项目（倍数法加权，价格 4.76 元，2026-08-03；日更停在 2026-08-10）', '框架化：10 条论点（7 条自动证伪）、27 张事实卡、14 条判断、2014—2025 年历史财务、10 个季度经营数据与 2026 年累计订单、2019 年以来的应收与减值序列、DDM＋现金桥接模型（2026—2035 年逐年假设、三情景、6 个单参数试验）、11 个跟踪事项；股价自动采集', '用户要求按长江电力、太阳纸业的架构再做中国建筑，作为独立项目', '2026 年半年报、1—9 月经营情况简报、业绩说明会问答、东方财富三大报表、岗底斯卖方一致预期与中报点评', '2023—2025 年东方财富数据与年报一致；模型 2026 年归母约 357 亿元，与中报后卖方区间（328—366 亿元）一致；Python 复算与数据库视图结果核对'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), '2026-10-23', '商业模式分析：补齐商业模式、产业链、竞争对手、壁垒与适配度，论点改为正反辩论', '论点与辩论、商业模式、产业链与五力、竞争对手、竞争壁垒、适配度；新增事实卡 7 张、来源 5 个；判断与跟踪事项的论点编号；判断 J-IMP 的反证改为引用 T8', '投资论点 10 条（无辩论）；商业模式、产业链、竞争对手、竞争壁垒、适配度均为空', '论点与辩论 8 条（7 条做过正反辩论，7 条带自动检查）：T1 规模与信用拿份额（原 T1）、T2 收入 2027 年见底（原 T2）、T3 毛利率（原 T3＋原 T8 的地产毛利率）、T4 利润变成现金（原 T4＋原 T10 的地方政府付款能力）、T5 负债（原 T5）、T6 治理与股东回报（原 T6＋T9）、T7 ROE（原 T7）、T8 减值见顶（原 T8＋T10 的隐性坏账）。商业模式 10、产业链 11、竞争对手 10、候选壁垒 7（局部优势 3、待验证 1、伪壁垒 3，没有真实壁垒）、适配度 15/40。', '用户要求把“研究”和“商业与壁垒”合并为“商业模式分析”，尽量减少冗余、确保内容完整', '建筑央企与保利发展 2025 年年报利润表（岗底斯取数）；中国建筑业协会 2025 年统计；中国海外发展 2025 年业绩公告；2024、2025 年年报片段（评级、成本构成、少数股东）；岗底斯同业对比；原论点与事实卡', 'tools/content_audit.py：重构前研究文字里 308 个带单位的数字，按原样找不到的 1 个（控股股东持股 57.7%，现写作更精确的 57.73%）；研究行从 70 行增加到 121 行，行与行之间共有长片段的行对 12 对（重构前 10 对，多是判断与事实卡之间）。估值不变：3.27、5.41、7.75 元（现金支持口径 1.89、5.40、7.75 元）；C09、C14 通过，C15 提示（15/40）。');

